import { logger } from './logger';
import { keys, delMany } from 'idb-keyval';

export interface DecodedAudioResult {
  int16Array: Int16Array;
  float32Array: Float32Array;
  sampleRate: number;
}

/**
 * Robustly parses and extracts pure 16-bit PCM speech audio from base64 data.
 * Crucially handles RIFF WAVE containers generated by Gemini 3.8 Flash TTS,
 * which append trailing C2PA / SynthID provenance metadata chunks (e.g. 'C2PA').
 * If trailing C2PA metadata chunks are not stripped, playing them as raw audio causes
 * loud, harsh static/screeching/crackle noise ("تشاش") at the exact end of the audio.
 */
export const extractAudioFromBase64 = (base64Audio: string): DecodedAudioResult => {
  const binary = atob(base64Audio);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }

  let sampleRate = 24000;
  let pcmBytes = bytes;

  // Check if buffer is a RIFF WAVE container
  if (
    bytes.length >= 12 &&
    bytes[0] === 0x52 && bytes[1] === 0x49 && bytes[2] === 0x46 && bytes[3] === 0x46 && // 'RIFF'
    bytes[8] === 0x57 && bytes[9] === 0x41 && bytes[10] === 0x56 && bytes[11] === 0x45    // 'WAVE'
  ) {
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    let offset = 12;

    while (offset + 8 <= bytes.length) {
      const chunkId = String.fromCharCode(
        bytes[offset],
        bytes[offset + 1],
        bytes[offset + 2],
        bytes[offset + 3]
      );
      const chunkSize = view.getUint32(offset + 4, true);

      if (chunkId === 'fmt ' && chunkSize >= 16) {
        sampleRate = view.getUint32(offset + 12, true);
      } else if (chunkId === 'data') {
        const start = offset + 8;
        const end = Math.min(start + chunkSize, bytes.length);
        // Isolate ONLY the genuine speech audio samples, completely stripping any trailing chunks (C2PA, metadata, etc.)
        pcmBytes = bytes.subarray(start, end);
        break;
      }

      offset += 8 + chunkSize;
      // Word alignment (2-byte padding for odd chunk sizes)
      if (chunkSize % 2 !== 0) offset++;
    }
  }

  // Ensure byte length is even for 16-bit PCM
  const validByteLength = pcmBytes.length - (pcmBytes.length % 2);
  const numSamples = validByteLength / 2;
  const int16Array = new Int16Array(numSamples);
  const dataView = new DataView(pcmBytes.buffer, pcmBytes.byteOffset, validByteLength);
  for (let i = 0; i < numSamples; i++) {
    int16Array[i] = dataView.getInt16(i * 2, true);
  }

  // Apply Anti-Pop Raised Cosine Envelope to the audio samples
  applyAntiPopEnvelopeInt16(int16Array);

  // Append 1024 zero-silence samples (~43ms) for 100% silent withdrawal / clean playback ending
  const SILENCE_PADDING = 1024;
  const float32Array = new Float32Array(int16Array.length + SILENCE_PADDING);
  for (let i = 0; i < int16Array.length; i++) {
    float32Array[i] = int16Array[i] / 32768;
  }
  for (let i = int16Array.length; i < float32Array.length; i++) {
    float32Array[i] = 0.0;
  }

  return { int16Array, float32Array, sampleRate };
};

/**
 * Extracts continuous 16-bit PCM speech samples for real-time streaming chunks (Live API).
 * Strips RIFF/WAVE/C2PA metadata ONLY if present, and performs ZERO fade-in/out or silence padding
 * so back-to-back scheduled audio buffers concatenate with 100% sample accuracy and no stuttering.
 */
export const extractStreamingPcmFromBase64 = (base64Audio: string): DecodedAudioResult => {
  const binary = atob(base64Audio);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }

  let sampleRate = 24000;
  let pcmBytes = bytes;

  if (
    bytes.length >= 12 &&
    bytes[0] === 0x52 && bytes[1] === 0x49 && bytes[2] === 0x46 && bytes[3] === 0x46 &&
    bytes[8] === 0x57 && bytes[9] === 0x41 && bytes[10] === 0x56 && bytes[11] === 0x45
  ) {
    const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
    let offset = 12;

    while (offset + 8 <= bytes.length) {
      const chunkId = String.fromCharCode(
        bytes[offset],
        bytes[offset + 1],
        bytes[offset + 2],
        bytes[offset + 3]
      );
      const chunkSize = view.getUint32(offset + 4, true);

      if (chunkId === 'fmt ' && chunkSize >= 16) {
        sampleRate = view.getUint32(offset + 12, true);
      } else if (chunkId === 'data') {
        const start = offset + 8;
        const end = Math.min(start + chunkSize, bytes.length);
        pcmBytes = bytes.subarray(start, end);
        break;
      }

      offset += 8 + chunkSize;
      if (chunkSize % 2 !== 0) offset++;
    }
  }

  const validByteLength = pcmBytes.length - (pcmBytes.length % 2);
  const numSamples = validByteLength / 2;
  const int16Array = new Int16Array(numSamples);
  const float32Array = new Float32Array(numSamples);
  const dataView = new DataView(pcmBytes.buffer, pcmBytes.byteOffset, validByteLength);

  for (let i = 0; i < numSamples; i++) {
    const s = dataView.getInt16(i * 2, true);
    int16Array[i] = s;
    float32Array[i] = s / 32768;
  }

  return { int16Array, float32Array, sampleRate };
};

export const applyAntiPopEnvelope = (float32Array: Float32Array): void => {
  if (!float32Array || float32Array.length === 0) return;
  const len = float32Array.length;

  // 1. Raised Cosine Fade-Out Window over 1024 samples (~43ms at 24kHz)
  const fadeOutSamples = Math.min(1024, Math.floor(len / 4));
  for (let i = 0; i < fadeOutSamples; i++) {
    const endIdx = len - 1 - i;
    const factor = 0.5 * (1 + Math.cos((Math.PI * (fadeOutSamples - i)) / fadeOutSamples));
    float32Array[endIdx] *= factor;
  }

  // 2. HARD ZERO TAIL: Force the last 128 samples (~5.3ms) to strictly 0.0
  const zeroTail = Math.min(128, len);
  for (let i = 0; i < zeroTail; i++) {
    float32Array[len - 1 - i] = 0.0;
  }

  // 3. Smooth Raised Cosine Fade-In over 256 samples (~10.6ms) to prevent start clicks
  const fadeInSamples = Math.min(256, Math.floor(len / 4));
  for (let i = 0; i < fadeInSamples; i++) {
    const factor = 0.5 * (1 - Math.cos((Math.PI * i) / fadeInSamples));
    float32Array[i] *= factor;
  }
};

export const applyAntiPopEnvelopeInt16 = (int16Array: Int16Array): void => {
  if (!int16Array || int16Array.length === 0) return;
  const len = int16Array.length;

  const fadeOutSamples = Math.min(1024, Math.floor(len / 4));
  for (let i = 0; i < fadeOutSamples; i++) {
    const endIdx = len - 1 - i;
    const factor = 0.5 * (1 + Math.cos((Math.PI * (fadeOutSamples - i)) / fadeOutSamples));
    int16Array[endIdx] = Math.round(int16Array[endIdx] * factor);
  }

  const zeroTail = Math.min(128, len);
  for (let i = 0; i < zeroTail; i++) {
    int16Array[len - 1 - i] = 0;
  }

  const fadeInSamples = Math.min(256, Math.floor(len / 4));
  for (let i = 0; i < fadeInSamples; i++) {
    const factor = 0.5 * (1 - Math.cos((Math.PI * i) / fadeInSamples));
    int16Array[i] = Math.round(int16Array[i] * factor);
  }
};

export const createWavHeader = (
  dataByteLength: number,
  sampleRate = 24000,
  numChannels = 1,
  bitsPerSample = 16
): ArrayBuffer => {
  const header = new ArrayBuffer(44);
  const view = new DataView(header);
  view.setUint32(0, 0x52494646, false); // "RIFF"
  view.setUint32(4, 36 + dataByteLength, true);
  view.setUint32(8, 0x57415645, false); // "WAVE"
  view.setUint32(12, 0x666d7420, false); // "fmt "
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true); // PCM format
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * numChannels * (bitsPerSample / 8), true);
  view.setUint16(32, numChannels * (bitsPerSample / 8), true);
  view.setUint16(34, bitsPerSample, true);
  view.setUint32(36, 0x64617461, false); // "data"
  view.setUint32(40, dataByteLength, true);
  return header;
};

export const base64ToWavBlob = (base64Audios: string[]): Blob | null => {
  if (!base64Audios || base64Audios.length === 0) return null;

  let totalSpeechSamples = 0;
  let masterSampleRate = 24000;
  const decodedAudios = base64Audios.map(base64 => {
    const decoded = extractAudioFromBase64(base64);
    totalSpeechSamples += decoded.int16Array.length;
    masterSampleRate = decoded.sampleRate || masterSampleRate;
    return decoded.int16Array;
  });

  // Append 1024 zero-silence samples (~43ms) at end of combined audio
  const SILENCE_PADDING = 1024;
  const result = new Int16Array(totalSpeechSamples + SILENCE_PADDING);
  let offset = 0;
  for (const arr of decodedAudios) {
    result.set(arr, offset);
    offset += arr.length;
  }

  // Zero out trailing silence padding
  for (let i = totalSpeechSamples; i < result.length; i++) {
    result[i] = 0;
  }

  const wavHeader = createWavHeader(result.length * 2, masterSampleRate, 1, 16);
  return new Blob([wavHeader, result], { type: 'audio/wav' });
};

export const base64ToPCM16 = (base64Audios: string[]): Blob | null => {
  return base64ToWavBlob(base64Audios);
};

export const downloadBlob = (blob: Blob, filename: string) => {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
};

export interface AudioPlaybackContext {
  audioCtx: AudioContext | null;
  gainNode: GainNode | null;
  sourceNode: AudioBufferSourceNode | null;
}

let globalAudioCtx: AudioContext | null = null;

export const getAudioContext = () => {
  if (!globalAudioCtx || globalAudioCtx.state === 'closed') {
    globalAudioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
  } else if (globalAudioCtx.state === 'suspended') {
    globalAudioCtx.resume();
  }
  return globalAudioCtx;
};

/**
 * Purges all cached audio files (TTS generated audio) from IndexedDB keyval store.
 * Returns the number of keys deleted.
 */
export const clearAudioCacheFromStorage = async (): Promise<number> => {
  try {
    const allKeys = await keys();
    const ttsKeys = allKeys.filter(
      (k: IDBValidKey) => typeof k === 'string' && (k.startsWith('tts_') || k.startsWith('tts_v'))
    ) as string[];

    if (ttsKeys.length > 0) {
      await delMany(ttsKeys);
      logger.info(`[AudioCache] Successfully cleared ${ttsKeys.length} cached audio items from IndexedDB.`);
    }
    return ttsKeys.length;
  } catch (err) {
    logger.error('[AudioCache] Error purging audio cache from IndexedDB:', err);
    return 0;
  }
};

export const playAudioBase64 = (
  base64: string,
  signal: AbortSignal,
  ttsVolume: number,
  ttsSpeed: number,
  contextRef: { current: AudioPlaybackContext }
): Promise<void> => {
  return new Promise((resolve, reject) => {
    try {
      const { float32Array, sampleRate } = extractAudioFromBase64(base64);

      const audioCtx = getAudioContext();
      contextRef.current.audioCtx = audioCtx;

      const gainNode = audioCtx.createGain();
      const speed = ttsSpeed || 1.0;
      const speechDuration = (float32Array.length - 1024) / sampleRate / speed;
      const totalDuration = float32Array.length / sampleRate / speed;

      // Synchronize start time precisely
      const startTime = audioCtx.currentTime + 0.01;

      gainNode.gain.setValueAtTime(ttsVolume, startTime);
      if (totalDuration > 0.05) {
        gainNode.gain.setValueAtTime(ttsVolume, startTime + Math.max(0, speechDuration - 0.02));
        gainNode.gain.linearRampToValueAtTime(0, startTime + totalDuration);
      }

      contextRef.current.gainNode = gainNode;
      gainNode.connect(audioCtx.destination);

      const buffer = audioCtx.createBuffer(1, float32Array.length, sampleRate);
      buffer.copyToChannel(float32Array, 0);

      const source = audioCtx.createBufferSource();
      source.buffer = buffer;
      source.playbackRate.value = speed;
      contextRef.current.sourceNode = source;
      source.connect(gainNode);

      let isCleanedUp = false;
      const cleanup = () => {
        if (isCleanedUp) return;
        isCleanedUp = true;
        try {
          source.disconnect();
        } catch (e) {}
        try {
          gainNode.disconnect();
        } catch (e) {}
        if (contextRef.current.audioCtx === audioCtx) {
          contextRef.current.gainNode = null;
          contextRef.current.sourceNode = null;
        }
      };

      source.onended = () => {
        cleanup();
        resolve();
      };

      signal.addEventListener('abort', () => {
        try {
          const abortNow = audioCtx.currentTime;
          gainNode.gain.cancelScheduledValues(abortNow);
          gainNode.gain.setValueAtTime(gainNode.gain.value, abortNow);
          gainNode.gain.linearRampToValueAtTime(0, abortNow + 0.02);
          setTimeout(() => {
            try { source.stop(); } catch (e) {}
            cleanup();
            resolve();
          }, 25);
        } catch (e) {
          cleanup();
          resolve();
        }
      });

      source.start(startTime);
    } catch (err) {
      logger.error('Audio setup error:', err);
      reject(new Error('خطأ في معالجة ملف الصوت.'));
    }
  });
};
